import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type InputOtpMode = "numeric" | "alphanumeric";
export type InputOtpSize = "sm" | "md" | "lg";
export type InputOtpStatus = "default" | "error" | "success";

export interface InputOtpProps
  extends Omit<
    React.HTMLAttributes<HTMLDivElement>,
    "defaultValue" | "onChange"
  > {
  length?: number;
  mode?: InputOtpMode;
  masked?: boolean;
  /** Group sizes for separated layout. Must sum to `length`, e.g. `[3, 3]` → 123 • 456 */
  groups?: number[];
  /** Character or node between digit groups. Defaults to `•`. */
  separator?: React.ReactNode;
  /** When true, calls `onComplete` once all slots are filled after user input. */
  autoSubmit?: boolean;
  /** Fires when all slots are filled after user input. Requires `autoSubmit`. Never fires on mount with a prefilled value. */
  onComplete?: (value: string) => void;
  /** Fires when all slots are filled after user input, without submitting. Never fires on mount with a prefilled value. */
  onFilled?: (value: string) => void;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Controls success/error visuals and which message is shown. */
  status?: InputOtpStatus;
  error?: React.ReactNode;
  success?: React.ReactNode;
  label?: React.ReactNode;
  hint?: React.ReactNode;
  disabled?: boolean;
  /** Locks input without the muted disabled styling — useful for verified / post-submit display. */
  readOnly?: boolean;
  /** Shows a verifying state: locks input, sets `aria-busy`, and pulses slots. */
  loading?: boolean;
  /** Screen-reader + helper copy while `loading` is true. */
  loadingMessage?: React.ReactNode;
  inputSize?: InputOtpSize;
  fullWidth?: boolean;
  autoFocus?: boolean;
  name?: string;
  containerClassName?: string;
  slotClassName?: string;
  separatorClassName?: string;
}

const OTP_CHECK_PATH = "M3.25 8.1 6.35 11.2 12.75 4.6";
const OTP_ERROR_PATH_A = "M4.5 4.5 11.5 11.5";
const OTP_ERROR_PATH_B = "M11.5 4.5 4.5 11.5";
const INPUT_OTP_STYLE_ID = "wensity-input-otp-styles";

const INPUT_OTP_STYLES = `
[data-wensity-otp] {
  --wensity-otp-ease-morph: cubic-bezier(0.32, 0.72, 0, 1);
  --wensity-otp-ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --wensity-otp-ease-draw: cubic-bezier(0.16, 1, 0.3, 1);
  --wensity-otp-success: var(--color-emerald-600, #059669);
  --wensity-otp-error: var(--color-red-600, #dc2626);
  --wensity-otp-tick-delay: 220ms;
  --wensity-otp-success-message-delay: 300ms;
}

.dark [data-wensity-otp] {
  --wensity-otp-success: var(--color-emerald-400, #34d399);
  --wensity-otp-error: var(--color-red-400, #f87171);
}

[data-wensity-otp-slot] {
  transition:
    border-color 320ms var(--wensity-otp-ease-morph),
    background-color 320ms var(--wensity-otp-ease-morph),
    box-shadow 320ms var(--wensity-otp-ease-morph),
    color 240ms var(--wensity-otp-ease-out),
    transform 320ms var(--wensity-otp-ease-morph),
    filter 260ms var(--wensity-otp-ease-draw);
}

[data-wensity-otp-slot] > input {
  color: inherit;
  transition: color 240ms var(--wensity-otp-ease-out);
}

[data-wensity-otp-slot][data-active] {
  border-color: color-mix(in srgb, var(--foreground) 28%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--foreground) 10%, transparent);
}

[data-wensity-otp-slot][data-filled]:not([data-active]) {
  background: color-mix(in srgb, var(--foreground) 3%, var(--background));
}

@keyframes wensity-otp-slot-enter {
  0% {
    transform: scale(0.94);
    filter: blur(2px);
    background-color: color-mix(in srgb, var(--foreground) 1%, var(--background));
  }
  55% {
    transform: scale(1.015);
    filter: blur(0);
  }
  100% {
    transform: scale(1);
    filter: blur(0);
  }
}

[data-wensity-otp-slot][data-enter] {
  animation: wensity-otp-slot-enter 340ms var(--wensity-otp-ease-morph);
}

[data-wensity-otp-slot][data-enter] > input {
  animation: wensity-otp-char-enter 280ms var(--wensity-otp-ease-draw);
}

@keyframes wensity-otp-char-enter {
  0% {
    opacity: 0.35;
    transform: translate3d(0, 2px, 0);
  }
  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

[data-wensity-otp][data-disabled] [data-wensity-otp-slot] {
  cursor: not-allowed;
  opacity: 0.45;
}

[data-wensity-otp][data-readonly] [data-wensity-otp-slot] {
  cursor: default;
}

[data-wensity-otp][data-readonly] [data-wensity-otp-slot] > input {
  cursor: default;
}

[data-wensity-otp][data-status="error"] [data-wensity-otp-slot] {
  border-color: color-mix(in srgb, var(--wensity-otp-error) 50%, transparent);
}

[data-wensity-otp][data-status="error"] [data-wensity-otp-slot][data-active] {
  border-color: color-mix(in srgb, var(--wensity-otp-error) 72%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--wensity-otp-error) 18%, transparent);
}

[data-wensity-otp][data-status="success"] [data-wensity-otp-slot] {
  border-color: color-mix(in srgb, var(--wensity-otp-success) 50%, transparent);
}

[data-wensity-otp][data-status="success"] [data-wensity-otp-slot][data-active] {
  border-color: color-mix(in srgb, var(--wensity-otp-success) 72%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--wensity-otp-success) 18%, transparent);
}

[data-wensity-otp][data-status="success"] [data-wensity-otp-slot][data-filled] {
  background: color-mix(in srgb, var(--wensity-otp-success) 6%, var(--background));
}

@keyframes wensity-otp-shake {
  0%,
  100% {
    transform: translate3d(0, 0, 0);
  }
  18% {
    transform: translate3d(-4px, 0, 0);
  }
  36% {
    transform: translate3d(4px, 0, 0);
  }
  54% {
    transform: translate3d(-2px, 0, 0);
  }
  72% {
    transform: translate3d(2px, 0, 0);
  }
}

[data-wensity-otp][data-shake="true"] [data-wensity-otp-slot] {
  animation: wensity-otp-shake 280ms var(--wensity-otp-ease-out);
}

[data-wensity-otp-status] {
  position: relative;
  display: inline-flex;
  width: 1.25rem;
  min-width: 1.25rem;
  margin-left: 0.25rem;
  flex: 0 0 1.25rem;
  overflow: hidden;
  align-items: center;
  justify-content: center;
}

[data-slot="input-otp-check"],
[data-slot="input-otp-error-a"],
[data-slot="input-otp-error-b"] {
  fill: none;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  opacity: 0;
  transition:
    stroke-dashoffset 140ms var(--wensity-otp-ease-draw) 0ms,
    opacity 120ms var(--wensity-otp-ease-draw) 0ms;
}

[data-wensity-otp][data-status="success"] [data-slot="input-otp-check"] {
  stroke-dashoffset: 0;
  opacity: 1;
  transition:
    stroke-dashoffset 280ms var(--wensity-otp-ease-draw) var(--wensity-otp-tick-delay),
    opacity 200ms var(--wensity-otp-ease-draw) var(--wensity-otp-tick-delay);
}

[data-wensity-otp][data-status="error"] [data-slot="input-otp-error-a"] {
  stroke-dashoffset: 0;
  opacity: 1;
  transition:
    stroke-dashoffset 240ms var(--wensity-otp-ease-draw) 0ms,
    opacity 180ms var(--wensity-otp-ease-draw) 0ms;
}

[data-wensity-otp][data-status="error"] [data-slot="input-otp-error-b"] {
  stroke-dashoffset: 0;
  opacity: 1;
  transition:
    stroke-dashoffset 240ms var(--wensity-otp-ease-draw) 80ms,
    opacity 180ms var(--wensity-otp-ease-draw) 80ms;
}

@keyframes wensity-otp-message-enter {
  from {
    opacity: 0;
    transform: translate3d(0, 4px, 0);
    filter: blur(2px);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
    filter: blur(0);
  }
}

[data-otp-message="success"] {
  animation: wensity-otp-message-enter 360ms var(--wensity-otp-ease-morph)
    var(--wensity-otp-success-message-delay) both;
}

[data-otp-message="error"] {
  animation: wensity-otp-message-enter 320ms var(--wensity-otp-ease-morph) 0ms both;
}

[data-otp-message="invalid"] {
  animation: wensity-otp-message-enter 220ms var(--wensity-otp-ease-morph) 0ms both;
}

[data-otp-message="loading"] {
  animation: wensity-otp-message-enter 240ms var(--wensity-otp-ease-morph) 0ms both;
}

@keyframes wensity-otp-loading-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.58;
  }
}

[data-wensity-otp][data-loading] [data-wensity-otp-slot] {
  animation: wensity-otp-loading-pulse 1200ms var(--wensity-otp-ease-morph) infinite;
  pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
  [data-wensity-otp-slot],
  [data-otp-message],
  [data-slot="input-otp-check"],
  [data-slot="input-otp-error-a"],
  [data-slot="input-otp-error-b"] {
    transition-duration: 0ms !important;
    transition-delay: 0ms !important;
  }

  [data-otp-message] {
    animation: none !important;
    opacity: 1;
    transform: none;
    filter: none;
  }

  [data-wensity-otp-slot][data-enter],
  [data-wensity-otp-slot][data-enter] > input,
  [data-wensity-otp][data-loading] [data-wensity-otp-slot],
  [data-wensity-otp][data-shake="true"] [data-wensity-otp-slot] {
    animation: none !important;
  }

  [data-slot="input-otp-check"],
  [data-slot="input-otp-error-a"],
  [data-slot="input-otp-error-b"] {
    stroke-dashoffset: 0;
  }

  [data-wensity-otp][data-status="success"] [data-slot="input-otp-check"],
  [data-wensity-otp][data-status="error"] [data-slot="input-otp-error-a"],
  [data-wensity-otp][data-status="error"] [data-slot="input-otp-error-b"] {
    opacity: 1;
  }
}
`;

function ensureInputOtpStyles() {
  if (typeof document === "undefined") return;
  if (document.getElementById(INPUT_OTP_STYLE_ID)) return;

  const style = document.createElement("style");
  style.id = INPUT_OTP_STYLE_ID;
  style.textContent = INPUT_OTP_STYLES;
  document.head.appendChild(style);
}

function OtpSuccessCheck() {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      fill="none"
      className="absolute inset-0 m-auto size-4 text-[var(--wensity-otp-success)]"
    >
      <path
        data-slot="input-otp-check"
        d={OTP_CHECK_PATH}
        pathLength={1}
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function OtpErrorX() {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      fill="none"
      className="absolute inset-0 m-auto size-4 text-[var(--wensity-otp-error)]"
    >
      <path
        data-slot="input-otp-error-a"
        d={OTP_ERROR_PATH_A}
        pathLength={1}
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
      <path
        data-slot="input-otp-error-b"
        d={OTP_ERROR_PATH_B}
        pathLength={1}
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  );
}

const slotSizes: Record<InputOtpSize, string> = {
  sm: "size-9 text-sm rounded-md",
  md: "size-11 text-base rounded-lg",
  lg: "size-[3.25rem] text-lg rounded-lg",
};

const separatorSizes: Record<InputOtpSize, string> = {
  sm: "text-sm",
  md: "text-base",
  lg: "text-lg",
};

const OTP_PASTE_ENTER_STAGGER_MS = 48;
const INVALID_CHAR_FEEDBACK_MS = 1600;

function otpPattern(mode: InputOtpMode, length: number): string {
  return mode === "numeric"
    ? `\\d{${length}}`
    : `[A-Za-z0-9]{${length}}`;
}

function invalidCharMessage(mode: InputOtpMode): string {
  return mode === "numeric" ? "Digits only." : "Letters and numbers only.";
}

function normalizeChar(char: string, mode: InputOtpMode): string {
  if (!char) return "";
  if (mode === "numeric") {
    return /^\d$/.test(char) ? char : "";
  }
  return /^[a-zA-Z0-9]$/.test(char) ? char.toUpperCase() : "";
}

function normalizeValue(
  value: string,
  mode: InputOtpMode,
  length: number,
): string {
  return value
    .split("")
    .map((char) => normalizeChar(char, mode))
    .filter(Boolean)
    .slice(0, length)
    .join("");
}

function resolveGroups(length: number, groups?: number[]): number[] {
  if (groups?.length) {
    const sum = groups.reduce((total, size) => total + size, 0);
    if (sum === length) return groups;
  }
  return [length];
}

function buildGroupRanges(groups: number[]): Array<[number, number]> {
  const ranges: Array<[number, number]> = [];
  let cursor = 0;
  for (const size of groups) {
    ranges.push([cursor, cursor + size]);
    cursor += size;
  }
  return ranges;
}

export const InputOtp = React.forwardRef<HTMLInputElement, InputOtpProps>(
  (
    {
      length = 6,
      mode = "numeric",
      masked = false,
      groups,
      separator = "•",
      autoSubmit = false,
      onComplete,
      onFilled,
      value,
      defaultValue = "",
      onValueChange,
      status: statusProp,
      error,
      success,
      label,
      hint,
      disabled = false,
      readOnly = false,
      loading = false,
      loadingMessage = "Verifying…",
      inputSize = "md",
      fullWidth = true,
      autoFocus = false,
      name,
      className,
      containerClassName,
      slotClassName,
      separatorClassName,
      id,
      "aria-describedby": ariaDescribedBy,
      "aria-invalid": ariaInvalid,
      ...props
    },
    ref,
  ) => {
    const reactId = React.useId();
    const rootId = id ?? `wensity-otp-${reactId}`;
    const labelId = label ? `${rootId}-label` : undefined;
    const hintId = hint ? `${rootId}-hint` : undefined;
    const errorId = error ? `${rootId}-error` : undefined;
    const successId = success ? `${rootId}-success` : undefined;
    const loadingId = loading ? `${rootId}-loading` : undefined;
    const invalidId = `${rootId}-invalid`;

    const isControlled = value !== undefined;
    const [uncontrolledValue, setUncontrolledValue] = React.useState(() =>
      normalizeValue(defaultValue, mode, length),
    );
    const currentValue = isControlled
      ? normalizeValue(value ?? "", mode, length)
      : uncontrolledValue;

    const [activeIndex, setActiveIndex] = React.useState<number | null>(
      autoFocus ? 0 : null,
    );
    const [enterIndex, setEnterIndex] = React.useState<number | null>(null);
    const [shake, setShake] = React.useState(false);
    const [invalidCharActive, setInvalidCharActive] = React.useState(false);
    const inputRefs = React.useRef<Array<HTMLInputElement | null>>([]);
    const autofillRef = React.useRef<HTMLInputElement | null>(null);
    const completedRef = React.useRef<string | null>(null);
    const hasInteractedRef = React.useRef(false);
    const enterTimeoutRef = React.useRef<number | null>(null);
    const enterStaggerTimeoutsRef = React.useRef<number[]>([]);
    const invalidCharTimeoutRef = React.useRef<number | null>(null);

    const isFieldDisabled = disabled || loading;
    const isInputLocked = isFieldDisabled || readOnly;
    const resolvedStatus: InputOtpStatus = statusProp ?? "default";
    const displayStatus: InputOtpStatus = loading ? "default" : resolvedStatus;
    const showInvalidCharFeedback =
      invalidCharActive && displayStatus === "default" && !loading;
    const showHint =
      Boolean(hint) &&
      !loading &&
      !showInvalidCharFeedback &&
      displayStatus !== "success" &&
      displayStatus !== "error";

    React.useLayoutEffect(() => {
      ensureInputOtpStyles();
    }, []);

    const clearEnterStaggerTimeouts = React.useCallback(() => {
      for (const timeoutId of enterStaggerTimeoutsRef.current) {
        window.clearTimeout(timeoutId);
      }
      enterStaggerTimeoutsRef.current = [];
    }, []);

    const triggerEnter = React.useCallback((index: number) => {
      if (enterTimeoutRef.current !== null) {
        window.clearTimeout(enterTimeoutRef.current);
      }
      setEnterIndex(index);
      enterTimeoutRef.current = window.setTimeout(() => {
        setEnterIndex(null);
        enterTimeoutRef.current = null;
      }, 360);
    }, []);

    const triggerEnterStaggered = React.useCallback(
      (startIndex: number, count: number) => {
        clearEnterStaggerTimeouts();
        for (let offset = 0; offset < count; offset += 1) {
          const timeoutId = window.setTimeout(() => {
            triggerEnter(startIndex + offset);
          }, offset * OTP_PASTE_ENTER_STAGGER_MS);
          enterStaggerTimeoutsRef.current.push(timeoutId);
        }
      },
      [clearEnterStaggerTimeouts, triggerEnter],
    );

    React.useEffect(() => {
      return () => {
        if (enterTimeoutRef.current !== null) {
          window.clearTimeout(enterTimeoutRef.current);
        }
        if (invalidCharTimeoutRef.current !== null) {
          window.clearTimeout(invalidCharTimeoutRef.current);
        }
        clearEnterStaggerTimeouts();
      };
    }, [clearEnterStaggerTimeouts]);

    const pulseInvalidChar = React.useCallback(() => {
      setInvalidCharActive(true);
      if (invalidCharTimeoutRef.current !== null) {
        window.clearTimeout(invalidCharTimeoutRef.current);
      }
      invalidCharTimeoutRef.current = window.setTimeout(() => {
        setInvalidCharActive(false);
        invalidCharTimeoutRef.current = null;
      }, INVALID_CHAR_FEEDBACK_MS);
    }, []);

    const mergeRef = React.useCallback(
      (index: number, node: HTMLInputElement | null) => {
        inputRefs.current[index] = node;
        if (index !== 0) return;
        if (typeof ref === "function") {
          ref(node);
        } else if (ref) {
          ref.current = node;
        }
      },
      [ref],
    );

    const describedBy =
      [
        ariaDescribedBy,
        loading
          ? loadingId
          : displayStatus === "error" && error
            ? errorId
            : displayStatus === "success" && success
              ? successId
              : showInvalidCharFeedback
                ? invalidId
                : showHint
                  ? hintId
                  : undefined,
      ]
        .filter(Boolean)
        .join(" ") || undefined;

    const valuePattern = React.useMemo(
      () => otpPattern(mode, length),
      [length, mode],
    );
    const slotPattern = mode === "numeric" ? "[0-9]" : "[A-Za-z0-9]";

    const groupSizes = React.useMemo(
      () => resolveGroups(length, groups),
      [groups, length],
    );
    const groupRanges = React.useMemo(
      () => buildGroupRanges(groupSizes),
      [groupSizes],
    );

    const setValue = React.useCallback(
      (nextValue: string) => {
        const normalized = normalizeValue(nextValue, mode, length);
        if (!isControlled) setUncontrolledValue(normalized);
        onValueChange?.(normalized);
        return normalized;
      },
      [isControlled, length, mode, onValueChange],
    );

    const focusSlot = React.useCallback((index: number) => {
      const clamped = Math.max(0, Math.min(index, length - 1));
      setActiveIndex(clamped);
      inputRefs.current[clamped]?.focus();
      inputRefs.current[clamped]?.select();
    }, [length]);

    const triggerShake = React.useCallback(() => {
      setShake(true);
      window.setTimeout(() => setShake(false), 320);
    }, []);

    React.useEffect(() => {
      if (loading || resolvedStatus !== "error") return;
      triggerShake();
    }, [loading, resolvedStatus, triggerShake]);

    React.useEffect(() => {
      if (currentValue.length !== length) {
        completedRef.current = null;
        return;
      }

      if (completedRef.current === currentValue) return;
      completedRef.current = currentValue;

      if (!hasInteractedRef.current) return;

      onFilled?.(currentValue);
      if (autoSubmit) {
        onComplete?.(currentValue);
      }
    }, [autoSubmit, currentValue, length, onComplete, onFilled]);

    const applyBulkValue = React.useCallback(
      (rawValue: string) => {
        const normalized = normalizeValue(rawValue, mode, length);
        if (!normalized) return;

        hasInteractedRef.current = true;
        setValue(normalized);

        triggerEnterStaggered(0, normalized.length);

        focusSlot(Math.min(normalized.length, length - 1));
      },
      [focusSlot, length, mode, setValue, triggerEnterStaggered],
    );

    const handleAutofillChange = React.useCallback(
      (event: React.ChangeEvent<HTMLInputElement>) => {
        const raw = event.target.value;
        if (!raw) return;
        applyBulkValue(raw);
        event.target.value = "";
      },
      [applyBulkValue],
    );

    const updateAtIndex = React.useCallback(
      (index: number, char: string) => {
        hasInteractedRef.current = true;
        const normalized = normalizeChar(char, mode);
        if (!normalized && char) return;

        const chars = currentValue.padEnd(length, " ").split("");
        chars[index] = normalized || " ";
        const next = chars.join("").trimEnd();
        setValue(next);

        if (normalized) {
          triggerEnter(index);
        }

        if (normalized && index < length - 1) {
          focusSlot(index + 1);
        }
      },
      [currentValue, focusSlot, length, mode, setValue, triggerEnter],
    );

    const clearSlotAtIndex = React.useCallback(
      (index: number) => {
        hasInteractedRef.current = true;
        const chars = currentValue.padEnd(length, " ").split("");
        if (!chars[index]?.trim()) return;
        chars[index] = " ";
        setValue(chars.join("").trimEnd());
      },
      [currentValue, length, setValue],
    );

    const handleKeyDown = React.useCallback(
      (index: number, event: React.KeyboardEvent<HTMLInputElement>) => {
        if (isInputLocked) return;
        if (event.nativeEvent.isComposing) return;

        if (event.key === "Backspace") {
          event.preventDefault();
          hasInteractedRef.current = true;
          const chars = currentValue.padEnd(length, " ").split("");

          if (chars[index]?.trim()) {
            chars[index] = " ";
            setValue(chars.join("").trimEnd());
            return;
          }

          if (index > 0) {
            chars[index - 1] = " ";
            setValue(chars.join("").trimEnd());
            focusSlot(index - 1);
          }
          return;
        }

        if (event.key === "Delete") {
          event.preventDefault();
          clearSlotAtIndex(index);
          return;
        }

        if (event.key === "Home") {
          event.preventDefault();
          focusSlot(0);
          return;
        }

        if (event.key === "End") {
          event.preventDefault();
          focusSlot(length - 1);
          return;
        }

        if (event.key === "ArrowLeft") {
          event.preventDefault();
          focusSlot(index - 1);
          return;
        }

        if (event.key === "ArrowRight") {
          event.preventDefault();
          focusSlot(index + 1);
          return;
        }

        if (
          event.key.length === 1 &&
          !event.ctrlKey &&
          !event.metaKey &&
          !event.altKey
        ) {
          const normalized = normalizeChar(event.key, mode);
          if (normalized) {
            event.preventDefault();
            updateAtIndex(index, normalized);
          } else {
            event.preventDefault();
            pulseInvalidChar();
          }
        }
      },
      [
        clearSlotAtIndex,
        currentValue,
        focusSlot,
        isInputLocked,
        length,
        mode,
        pulseInvalidChar,
        setValue,
        updateAtIndex,
      ],
    );

    const handlePaste = React.useCallback(
      (event: React.ClipboardEvent<HTMLInputElement>) => {
        if (isInputLocked) return;
        event.preventDefault();
        const raw = event.clipboardData.getData("text");
        const normalized = normalizeValue(raw, mode, length);
        if (!normalized && raw.trim()) {
          pulseInvalidChar();
          return;
        }
        applyBulkValue(raw);
      },
      [applyBulkValue, isInputLocked, length, mode, pulseInvalidChar],
    );

    const slots = groupRanges.flatMap(([start, end], groupIndex) => {
      const groupSlots = Array.from({ length: end - start }, (_, offset) => {
        const index = start + offset;
        const slotValue = currentValue[index] ?? "";
        const isFilled = slotValue.length > 0;
        const isActive = activeIndex === index;

        return (
          <span
            key={index}
            data-wensity-otp-slot=""
            data-filled={isFilled ? "" : undefined}
            data-active={isActive ? "" : undefined}
            data-enter={enterIndex === index ? "" : undefined}
            className={cn(
              "relative inline-flex items-center justify-center border border-[var(--border)] bg-[var(--background)] font-medium tabular-nums text-[var(--foreground)]",
              slotSizes[inputSize],
              slotClassName,
            )}
          >
            <input
              ref={(node) => mergeRef(index, node)}
              id={index === 0 ? rootId : undefined}
              type={masked ? "password" : "text"}
              inputMode={mode === "numeric" ? "numeric" : "text"}
              pattern={slotPattern}
              autoComplete="off"
              aria-label={`Character ${index + 1} of ${length}`}
              disabled={isFieldDisabled}
              readOnly={readOnly}
              value={slotValue}
              maxLength={index === 0 ? length : 1}
              autoFocus={autoFocus && index === 0 && !readOnly}
              onFocus={() => setActiveIndex(index)}
              onBlur={() =>
                setActiveIndex((current) => (current === index ? null : current))
              }
              onChange={(event) => {
                if (isInputLocked) return;
                const raw = event.target.value;
                if (raw.length > 1) {
                  applyBulkValue(raw);
                  return;
                }
                if (raw.length === 1) {
                  if (!normalizeChar(raw, mode)) {
                    pulseInvalidChar();
                    return;
                  }
                  updateAtIndex(index, raw);
                  return;
                }
                clearSlotAtIndex(index);
              }}
              onKeyDown={(event) => handleKeyDown(index, event)}
              onPaste={handlePaste}
              className={cn(
                "size-full bg-transparent text-center font-medium tabular-nums text-inherit outline-none",
                "placeholder:text-[var(--muted-foreground)]/35",
                "disabled:cursor-not-allowed disabled:opacity-45",
                "focus-visible:outline-none",
              )}
            />
          </span>
        );
      });

      if (groupIndex === 0) return groupSlots;

      return [
        <span
          key={`separator-${groupIndex}`}
          aria-hidden="true"
          className={cn(
            "select-none px-1 font-medium text-[var(--muted-foreground)]/45",
            separatorSizes[inputSize],
            separatorClassName,
          )}
        >
          {separator}
        </span>,
        ...groupSlots,
      ];
    });

    return (
      <div
        className={cn(
          "flex flex-col gap-1.5",
          fullWidth ? "w-full" : "w-fit",
          containerClassName,
        )}
      >
        {label ? (
          <label
            id={labelId}
            htmlFor={rootId}
            className="text-[13px] font-normal leading-none tracking-[-0.01em] text-[var(--foreground)]"
          >
            {label}
          </label>
        ) : null}

        <div
          role="group"
          aria-labelledby={label ? labelId : undefined}
          aria-describedby={describedBy}
          aria-busy={loading || undefined}
          aria-invalid={
            ariaInvalid ?? (displayStatus === "error" ? true : undefined)
          }
          data-wensity-otp=""
          data-status={displayStatus}
          data-shake={shake ? "true" : undefined}
          data-loading={loading ? "" : undefined}
          data-disabled={isFieldDisabled ? "" : undefined}
          data-readonly={readOnly ? "" : undefined}
          className={cn("relative", fullWidth ? "w-full" : "w-fit", className)}
          {...props}
        >
          <input
            ref={autofillRef}
            data-wensity-otp-autofill=""
            type="text"
            inputMode={mode === "numeric" ? "numeric" : "text"}
            autoComplete="one-time-code"
            pattern={valuePattern}
            tabIndex={-1}
            aria-hidden="true"
            disabled={isFieldDisabled}
            readOnly={readOnly}
            defaultValue=""
            onChange={handleAutofillChange}
            className="sr-only"
          />
          <div
            data-wensity-otp-track=""
            className="flex items-center gap-2"
          >
            {slots}
            <span
              data-wensity-otp-status=""
              aria-hidden={displayStatus === "default"}
              className="pointer-events-none relative size-5 shrink-0"
            >
              <OtpErrorX />
              <OtpSuccessCheck />
            </span>
          </div>

          {name ? (
            <input
              type="text"
              name={name}
              value={currentValue}
              readOnly
              tabIndex={-1}
              aria-hidden="true"
              pattern={valuePattern}
              className="sr-only"
            />
          ) : null}
        </div>

        <div aria-live="polite" aria-atomic="true" className="relative min-h-5">
          <div className="grid [&>*]:col-start-1 [&>*]:row-start-1">
            {showHint ? (
              <p
                id={hintId}
                data-otp-message="hint"
                className="text-[12px] leading-5 text-[var(--muted-foreground)]/80"
              >
                {hint}
              </p>
            ) : null}
            {loading ? (
              <p
                id={loadingId}
                data-otp-message="loading"
                className="text-[12px] leading-5 text-[var(--muted-foreground)]/80"
              >
                {loadingMessage}
              </p>
            ) : displayStatus === "error" && error ? (
              <p
                id={errorId}
                data-otp-message="error"
                className="text-[12px] leading-5 text-[var(--wensity-otp-error)]"
              >
                {error}
              </p>
            ) : displayStatus === "success" && success ? (
              <p
                id={successId}
                data-otp-message="success"
                className="text-[12px] leading-5 font-medium text-[var(--wensity-otp-success)]"
              >
                {success}
              </p>
            ) : showInvalidCharFeedback ? (
              <p
                id={invalidId}
                data-otp-message="invalid"
                className="text-[12px] leading-5 text-[var(--wensity-otp-error)]"
              >
                {invalidCharMessage(mode)}
              </p>
            ) : null}
          </div>
        </div>
      </div>
    );
  },
);

InputOtp.displayName = "InputOtp";
